import javax.tools.*;
import com.sun.source.tree.*;
import com.sun.source.util.*;
import java.util.*;
import java.net.*;

public class AstDump {
	public static void main(String[] args) throws Exception {
		JavaCompiler c = ToolProvider.getSystemJavaCompiler();
		StandardJavaFileManager fm = c.getStandardFileManager(null, null, null);
		String src = "import lombok.NonNull;\npublic record R(@NonNull int [] a, int @NonNull [] b, int [] @NonNull [] c) {}\n";
		JavaFileObject f = new SimpleJavaFileObject(URI.create("string:///R.java"), JavaFileObject.Kind.SOURCE) {
			public CharSequence getCharContent(boolean b) { return src; }
		};
		JavacTask task = (JavacTask) c.getTask(null, fm, null, Arrays.asList("-proc:none"), null, Arrays.asList(f));
		for (CompilationUnitTree cu : task.parse()) {
			new TreeScanner<Void, Void>() {
				public Void visitVariable(VariableTree v, Void p) {
					System.out.println("VAR " + v.getName() + " typeText=" + v.getType() + " typeClass=" + v.getType().getClass().getSimpleName());
					dump(v.getType(), "  ");
					return super.visitVariable(v, p);
				}
				void dump(Tree t, String ind) {
					if (t == null) return;
					System.out.println(ind + t.getClass().getSimpleName() + " text=" + t);
					if (t instanceof AnnotatedTypeTree) {
						AnnotatedTypeTree a = (AnnotatedTypeTree) t;
						System.out.println(ind + "  annotations=" + a.getAnnotations());
						dump(a.getUnderlyingType(), ind + "  ");
					} else if (t instanceof ArrayTypeTree) {
						dump(((ArrayTypeTree) t).getType(), ind + "  ");
					}
				}
			}.scan(cu, null);
		}
	}
}

